\begin{tikzpicture}[
  scale=0.85, every node/.style={transform shape},
  cell/.style={rectangle, draw=black!70, fill=blue!5, very thick, rounded corners=8pt, minimum width=9cm, minimum height=6cm},
  op/.style={circle, draw=black!80, fill=yellow!20, thick, minimum size=0.6cm, inner sep=0pt},
  gate/.style={rectangle, draw=black!80, fill=orange!25, thick, rounded corners=3pt, minimum width=0.8cm, minimum height=0.6cm, font=\small},
  conn/.style={-stealth, thick, draw=black!75},
  highway/.style={-stealth, very thick, draw=red!70!black}
]
  % Cell container
  \node[cell] (lstm) at (4,2.5) {};
  \node[above right, font=\bfseries\small, text=blue!80!black] at (lstm.north west) {Cellule LSTM};

  % Inputs & States
  \node (x) at (1, -1.2) {$x_t$};
  \node (h_prev) at (-1.5, 0.5) {$h_{t-1}$};
  \node (c_prev) at (-1.5, 4.5) {$C_{t-1}$};

  % Gates
  \node[gate] (f_gate) at (1.5, 1.8) {$\sigma$};
  \node[below, font=\scriptsize] at (f_gate.south) {Forget $f_t$};
  \node[gate] (i_gate) at (3.0, 1.8) {$\sigma$};
  \node[below, font=\scriptsize] at (i_gate.south) {Input $i_t$};
  \node[gate] (c_tilde) at (4.5, 1.8) {$\tanh$};
  \node[below, font=\scriptsize] at (c_tilde.south) {$\tilde{C}_t$};
  \node[gate] (o_gate) at (6.0, 1.8) {$\sigma$};
  \node[below, font=\scriptsize] at (o_gate.south) {Output $o_t$};

  % Cell State Highway Operations
  \node[op] (mult_c) at (1.5, 4.5) {$\odot$};
  \node[op] (add_c) at (3.75, 4.5) {$\oplus$};
  \node (c_next) at (9.5, 4.5) {$C_t$};

  % Hidden State Operations
  \node[op] (mult_i_c) at (3.75, 3.2) {$\odot$};
  \node[gate] (tanh_c) at (6.8, 3.5) {$\tanh$};
  \node[op] (mult_h) at (6.8, 0.5) {$\odot$};
  \node (h_next) at (9.5, 0.5) {$h_t$};

  % Gradient Highway
  \draw[highway] (c_prev) -- (mult_c);
  \draw[highway] (mult_c) -- node[above, font=\scriptsize, text=red!60!black] {CEC : Autoroute additive du gradient} (add_c);
  \draw[highway] (add_c) -- (c_next);

  % Feedforward & Gating
  \draw[conn] (x) |- (f_gate);
  \draw[conn] (x) |- (i_gate);
  \draw[conn] (x) |- (c_tilde);
  \draw[conn] (x) |- (o_gate);
  \draw[conn] (h_prev) -- (0.5, 0.5) |- (f_gate);
  \draw[conn] (0.5, 0.5) |- (i_gate);
  \draw[conn] (0.5, 0.5) |- (c_tilde);
  \draw[conn] (0.5, 0.5) |- (o_gate);

  \draw[conn] (f_gate) -- (mult_c);
  \draw[conn] (i_gate) |- (mult_i_c);
  \draw[conn] (c_tilde) |- (mult_i_c);
  \draw[conn] (mult_i_c) -- (add_c);

  \draw[conn] (add_c.east) -| (tanh_c.north);
  \draw[conn] (tanh_c) -- (mult_h);
  \draw[conn] (o_gate) |- (mult_h);
  \draw[conn] (mult_h) -- (h_next);
\end{tikzpicture}
